-- แผน 06 ปีงบประมาณ 2570 (นำเข้าจากไฟล์ "1. แผน 06 Final (2-10-69) ทะเบียนคุมการใช้จ่ายงปม. 70.xlsx" ชีต "(ต้นฉบับ)ฝ่ายยุทธฯ-แผน 06")
-- ใช้กับหน้า bi/reports/Budget_Procurement_ByAsset  | รันซ้ำได้ (ล้างแผน 06 ปี 2570 แล้วนำเข้าใหม่)
USE NMU_ERP
GO
IF OBJECT_ID('dbo.sp_plan_budget') IS NULL
CREATE TABLE dbo.sp_plan_budget (
	sp_plan_budget_id int IDENTITY(1,1) PRIMARY KEY,
	plan_code nvarchar(40) NOT NULL,
	i_year int NOT NULL,
	c_group_name nvarchar(200) NULL,
	c_name nvarchar(max) NULL,
	f_budget decimal(18,2) NULL,
	dc_expense_budget_type_id int NULL,
	c_expense_type nvarchar(200) NULL,
	c_expense_type_adj nvarchar(200) NULL,
	c_status nvarchar(100) NULL,
	c_doc_ref nvarchar(100) NULL,
	f_approve_amt decimal(18,2) NULL,
	f_remain decimal(18,2) NULL,
	c_pr_code nvarchar(100) NULL,
	i_enabled tinyint NOT NULL DEFAULT 1,
	d_create datetime NOT NULL DEFAULT GETDATE()
)
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='UX_sp_plan_budget_plan_code')
CREATE UNIQUE INDEX UX_sp_plan_budget_plan_code ON dbo.sp_plan_budget(plan_code)
GO
DELETE FROM dbo.sp_plan_budget WHERE plan_code LIKE '06-%-2570'
GO
GO
GO
GO
GO
-- แปลงรหัสแหล่งเงินในไฟล์แผน (ชีต "คำนิยาม": 01 กทม., 02 รัฐบาล, 03 เงินรายได้ส่วนงาน, 04 เงินสะสมส่วนงาน)
-- เป็น dc_expense_budget_type_id ของระบบ (4, 5, 49, 8) ; ค่าอื่นที่ไม่ใช่ 1-4 (เช่นค่าวันที่จาก Excel) ตั้งเป็น NULL
UPDATE dbo.sp_plan_budget SET dc_expense_budget_type_id = CASE dc_expense_budget_type_id WHEN 1 THEN 4 WHEN 2 THEN 5 WHEN 3 THEN 49 WHEN 4 THEN 8 ELSE NULL END
WHERE plan_code LIKE '06-%-2570'
GO
